const $=s=>document.querySelector(s);let lang=localStorage.getItem('bayan-lab-lang')||'ar',category='all',query='',current=null,values={},answered=false;const completed=new Set(JSON.parse(localStorage.getItem('bayan-lab-progress')||'[]'));const t=(a,e)=>lang==='ar'?a:e;const n=v=>new Intl.NumberFormat(lang==='ar'?'ar-SA':'en-US',{maximumFractionDigits:2}).format(v);const groups=[['basics','الأساسيات','Foundations','◈'],['cycle','الدورة المحاسبية','Accounting cycle','▤'],['statements','القوائم المالية','Financial statements','▥'],['assets','الأصول والمخزون','Assets & inventory','◇'],['costs','التكاليف والإدارة','Cost & management','◎'],['analysis','التحليل المالي','Financial analysis','↗']];
const lessons=[
['equation','basics','المعادلة المحاسبية','Accounting equation','eq','كل عملية تغيّر عناصر المعادلة، مع بقاء الأصول مساوية للالتزامات وحقوق الملكية.','Every transaction changes the equation while assets remain equal to liabilities plus equity.'],
['double','basics','القيد المزدوج وطبيعة الحسابات','Double entry & account nature','debit','افهم طبيعة الحساب أولًا. لتخفيض رصيده المعتاد أو إقفاله نسجل عكس طبيعته: المدينة بالدائن، والدائنة بالمدين. أما تصحيح الخطأ فيعتمد على أثره وقد يتطلب عكس القيد الخاطئ.','Identify the normal balance first. Reduce or close a normal balance with the opposite side: credit a debit balance, debit a credit balance. Error correction depends on its effect and may require reversing the wrong entry.'],
['accrual','basics','الاستحقاق والأساس النقدي','Accrual vs. cash basis','accrual','في مثال الخدمة، يُثبت الإيراد عند تقديمها على أساس الاستحقاق، وعند التحصيل على الأساس النقدي.','In this service example, accrual accounting records revenue when earned; cash accounting records it when collected.'],
['journal','cycle','قيود اليومية','Journal entries','debit','نحوّل العملية إلى حساب مدين وآخر دائن، ثم نثبت المبلغ المتساوي في الطرفين.','Translate an event into debit and credit accounts, then record equal amounts on both sides.'],
['ledger','cycle','الأستاذ وحسابات T','Ledger & T-accounts','debit','حساب T يجمع حركة حساب واحد: المدين يسارًا والدائن يمينًا، حتى عند استخدام الواجهة العربية.','A T-account organizes one account: debit on the left and credit on the right, including in the Arabic interface.'],
['trial','cycle','ميزان المراجعة','Trial balance','debit','يجمع أرصدة الحسابات للتحقق من تساوي المدين والدائن. التساوي لا يكشف العمليات المحذوفة أو كل أخطاء التصنيف.','Account balances check debit-credit equality. A balanced trial balance cannot detect omitted entries or every classification error.'],
['adjust','cycle','التسويات والمصروف المقدم','Adjusting & prepaid expenses','adjust','التأمين المدفوع مقدمًا أصل. مع انقضاء التغطية، يُنقل الجزء المستهلك إلى المصروف.','Prepaid insurance is an asset. As coverage expires, the consumed portion becomes an expense.'],
['balance','statements','قائمة المركز المالي','Balance sheet','eq','تعرض الأصول والالتزامات وحقوق الملكية في تاريخ محدد. المثال يوضح أثر التمويل والشراء على المركز المالي.','Shows assets, liabilities and equity at a specific date. Explore how financing and purchases affect financial position.'],
['income','statements','قائمة الدخل','Income statement','income','صافي الربح في هذا المثال يساوي الإيرادات ناقص تكلفة المبيعات والمصروفات التشغيلية؛ لا يمثل الرصيد النقدي.','In this example, net profit equals revenue minus cost of sales and operating expenses; it is not the cash balance.'],
['cash','statements','قائمة التدفقات النقدية','Cash flow statement','cash','تُصنف الحركة النقدية إلى تشغيل واستثمار وتمويل. شراء المعدات تدفق استثماري، والقرض تدفق تمويلي.','Cash movements are operating, investing or financing. Equipment purchases are investing outflows; loans are financing inflows.'],
['equity','statements','التغير في حقوق الملكية','Changes in equity','equity','الرصيد الختامي = الرصيد الافتتاحي + استثمارات المالك + الربح − المسحوبات. المسحوبات ليست مصروفًا.','Closing equity equals opening equity plus owner investment plus profit minus drawings. Drawings are not an expense.'],
['depreciation','assets','الإهلاك بالقسط الثابت','Straight-line depreciation','dep','الإهلاك توزيع تكلفة الأصل القابلة للإهلاك على عمره الإنتاجي؛ وليس تقييمًا لسعره في السوق.','Depreciation allocates an asset’s depreciable cost over its useful life; it does not measure its market price.'],
['book','assets','القيمة الدفترية','Carrying amount','dep','القيمة الدفترية = التكلفة − مجمع الإهلاك في هذا المثال، بافتراض عدم وجود انخفاض قيمة.','Carrying amount equals cost minus accumulated depreciation here, assuming no impairment.'],
['inventory','assets','FIFO والمتوسط المرجح','FIFO & weighted average','inventory','قارن تكلفة البيع والمخزون عند شراء 100 وحدة بسعر 10، ثم 100 بسعر 16، في نظام جرد دوري مبسط.','Compare cost of sales and inventory after buying 100 units at 10, then 100 at 16, in a simplified periodic system.'],
['receivables','assets','الذمم ومخصص الخسائر','Receivables & allowance','receivable','المخصص يخفض صافي الذمم. النموذج يستخدم نسبة مبسطة للتعليم؛ التقدير العملي يتطلب معلومات ائتمانية إضافية.','An allowance reduces net receivables. This teaching model uses a simple percentage; real estimates require further credit information.'],
['fixed','costs','التكاليف الثابتة والمتغيرة','Fixed & variable costs','be','ضمن النطاق الملائم، تبقى التكلفة الثابتة الإجمالية ثابتة، وتتغير التكلفة المتغيرة الإجمالية مع حجم الإنتاج.','Within the relevant range, total fixed cost stays constant while total variable cost changes with output.'],
['contribution','costs','هامش المساهمة','Contribution margin','be','سعر الوحدة ناقص تكلفتها المتغيرة يعطي مساهمتها في تغطية التكاليف الثابتة، ثم تحقيق الربح.','Unit price minus unit variable cost gives the amount available to cover fixed costs and then profit.'],
['breakeven','costs','نقطة التعادل','Break-even point','be','عند التعادل تتساوى الإيرادات والتكاليف. يفترض النموذج منتجًا واحدًا وسعرًا وتكلفة وحدة ثابتين.','At break-even, revenue equals costs. This model assumes one product and constant unit price and variable cost.'],
['budget','costs','الموازنة وانحراف المصروف','Budget & expense variance','budget','قارن المصروف الفعلي بالمخطط: زيادة المصروف انحراف غير ملائم في هذا النموذج، وتخفيضه ملائم.','Compare actual with planned expense: overspending is unfavorable in this model; underspending is favorable.'],
['liquidity','analysis','نسبة التداول','Current ratio','ratio','الأصول المتداولة ÷ الالتزامات المتداولة. النسبة مؤشر للسيولة، وتفسيرها يعتمد على القطاع وجودة الأصول.','Current assets divided by current liabilities. Interpretation depends on the industry and asset quality.'],
['margin','analysis','هامش صافي الربح','Net profit margin','margin','صافي الربح ÷ الإيرادات × 100. يوضح ما يتبقى من كل وحدة مبيعات بعد مصروفات المثال.','Net profit divided by revenue times 100. Shows the profit retained from each unit of sales in this example.'],
['leverage','analysis','نسبة الالتزامات إلى الأصول','Liabilities-to-assets ratio','leverage','إجمالي الالتزامات ÷ إجمالي الأصول × 100. يعرض الجزء الممول بالالتزامات؛ لا يكفي وحده لتقييم المخاطر.','Total liabilities divided by total assets times 100. Shows the share financed by liabilities; it cannot assess risk alone.'],
['present','analysis','القيمة الحالية','Present value','pv','المبلغ المستقبلي يُخصم إلى اليوم. نفترض دفعة واحدة في نهاية المدة ومعدل خصم سنوي ثابتًا.','Discount a future amount back to today. Assumes one payment at the end of the period and a constant annual discount rate.']
].map(x=>({id:x[0],group:x[1],ar:x[2],en:x[3],mode:x[4],descAr:x[5],descEn:x[6]}));
const name=l=>t(l.ar,l.en);const desc=l=>t(l.descAr,l.descEn);const formulas={eq:'Assets = Liabilities + Equity',debit:'Total debits = Total credits',accrual:'Receivables = Earned revenue − Cash collected',adjust:'Expense = Prepayment × Months elapsed / 12',income:'Net profit = Revenue − Cost of sales − Operating expenses',cash:'Closing cash = Opening cash + Operating + Investing + Financing',equity:'Closing equity = Opening equity + Investment + Profit − Drawings',dep:'Annual depreciation = (Cost − Residual value) / Useful life',inventory:'Cost available = Cost of sales + Closing inventory',receivable:'Net receivables = Gross receivables − Allowance',be:'Break-even units = Fixed costs / (Unit price − Unit variable cost)',budget:'Expense variance = Actual − Budget',ratio:'Current ratio = Current assets / Current liabilities',margin:'Net margin = Net profit / Revenue × 100',leverage:'Liabilities-to-assets = Liabilities / Assets × 100',pv:'PV = FV / (1 + r)ⁿ'};
const arabicFormulas={"eq": "الأصول = الالتزامات + حقوق الملكية", "debit": "مجموع المدين = مجموع الدائن", "accrual": "الذمم المدينة = الإيراد المكتسب − النقد المحصّل", "adjust": "المصروف = الدفعة المقدمة × الأشهر المنقضية ÷ ١٢", "income": "صافي الربح = الإيرادات − تكلفة المبيعات − مصروفات التشغيل", "cash": "نقد النهاية = نقد البداية + صافي التشغيل + صافي الاستثمار + صافي التمويل", "equity": "ملكية النهاية = ملكية البداية + الاستثمار + الربح − المسحوبات", "dep": "الإهلاك السنوي = (التكلفة − القيمة المتبقية) ÷ العمر الإنتاجي", "inventory": "تكلفة المخزون المتاح = تكلفة المبيعات + مخزون النهاية", "receivable": "صافي الذمم المدينة = إجمالي الذمم المدينة − المخصص", "be": "وحدات التعادل = التكاليف الثابتة ÷ (سعر الوحدة − تكلفتها المتغيرة)", "budget": "انحراف المصروف = المصروف الفعلي − المصروف المخطط", "ratio": "نسبة التداول = الأصول المتداولة ÷ الالتزامات المتداولة", "margin": "هامش صافي الربح = صافي الربح ÷ الإيرادات × ١٠٠", "leverage": "نسبة الالتزامات إلى الأصول = الالتزامات ÷ الأصول × ١٠٠", "pv": "القيمة الحالية = القيمة المستقبلية ÷ ((١ + معدل الخصم) ^ عدد السنوات)"};
function formulaMarkup(mode){return `<div class="formula">${lang==='ar'?`<div class="formula-ar" lang="ar" dir="rtl">${arabicFormulas[mode]}</div>`:''}<div class="formula-en" lang="en" dir="ltr">${formulas[mode]}</div></div>`;}
const illustrationCaptions={"equation": ["ميزان يوضح تساوي الأصول مع الالتزامات وحقوق الملكية.", "A balanced scale shows assets equaling liabilities plus equity."], "double": ["قيد واحد ينتقل بين طرف مدين وطرف دائن بالمبلغ نفسه.", "One entry connects a debit and a credit of the same amount."], "normal": ["جانب الزيادة يختلف باختلاف نوع الحساب.", "The side that increases a balance depends on the account type."], "accrual": ["تقديم الخدمة وتحصيل المقابل قد يحدثان في وقتين مختلفين.", "Earning a service fee and collecting it may happen at different times."], "journal": ["من مستند العملية إلى قيد يومية متوازن.", "From a source document to a balanced journal entry."], "ledger": ["تُرحّل قيود اليومية لتجميع حركة كل حساب في الأستاذ.", "Journal entries are posted to organize each account in the ledger."], "trial": ["مجموع الأرصدة المدينة يساوي مجموع الأرصدة الدائنة.", "Total debit balances equal total credit balances."], "adjust": ["بعد ٣ أشهر من سنة التغطية، استُهلك ربع التأمين المقدم.", "After 3 months of annual coverage, a quarter of prepaid insurance is consumed."], "balance": ["صورة للمركز المالي: الموارد ومصادر تمويلها في تاريخ محدد.", "A snapshot of financial position: resources and financing at a specific date."], "income": ["إيراد ١٠٠ ناقص مصروفات ٦٠ يترك ربحًا قدره ٤٠.", "Revenue of 100 minus expenses of 60 leaves profit of 40."], "cash": ["التشغيل والاستثمار والتمويل تشكّل حركة النقد.", "Operating, investing and financing activities explain cash movements."], "equity": ["تتحرك الملكية من رصيد البداية إلى النهاية بالاستثمار والربح والمسحوبات.", "Equity moves from opening to closing through investment, profit and drawings."], "depreciation": ["القيمة الدفترية تنخفض تدريجيًا مع توزيع تكلفة الأصل.", "Carrying amount gradually falls as asset cost is allocated."], "book": ["طرح مجمع الإهلاك من التكلفة يعطي القيمة الدفترية.", "Subtract accumulated depreciation from cost to get carrying amount."], "inventory": ["في FIFO، تُحمّل تكلفة الدفعات الأقدم على البيع أولًا.", "Under FIFO, older batch costs are assigned to sales first."], "receivables": ["المخصص يُطرح من إجمالي الذمم للوصول إلى صافيها.", "Subtract the allowance from gross receivables to find the net amount."], "fixed": ["الثابتة لا تتغير إجمالًا ضمن النطاق الملائم، والمتغيرة ترتفع مع الحجم.", "Total fixed cost stays level within the relevant range; variable cost rises with volume."], "contribution": ["يتوزع سعر البيع بين تكلفة متغيرة وهامش مساهمة.", "Selling price is split between variable cost and contribution margin."], "breakeven": ["تقاطع الإيرادات والتكاليف هو نقطة التعادل.", "The intersection of revenue and total cost is the break-even point."], "budget": ["مصروف فعلي ١٢٠ مقابل مخطط ١٠٠: تجاوز بمقدار ٢٠.", "Actual expense of 120 versus a budget of 100: an overspend of 20."], "liquidity": ["أصول متداولة ٢٠٠ تغطي التزامات متداولة ١٠٠ مرتين.", "Current assets of 200 cover current liabilities of 100 twice."], "margin": ["ربح ٢٠ من إيراد ١٠٠ يعادل هامشًا قدره ٢٠٪.", "Profit of 20 on revenue of 100 gives a 20% margin."], "leverage": ["الالتزامات تموّل ٤٠٪ من الأصول في هذا المثال.", "Liabilities finance 40% of assets in this example."], "present": ["نخصم مبلغ المستقبل للوصول إلى قيمته اليوم.", "Discount the future amount to obtain its value today."]};
function lessonArt(l){return `<img class="concept-image" src="images/${l.id}.svg" alt="${t(...illustrationCaptions[l.id])}" width="320" height="155" loading="lazy" decoding="async">`;}
function render(){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.title=t('بيان — المحاسبة بالصورة والتجربة','Bayan — Accounting made visible');$('#sidebar').innerHTML=`<div class="sidebar-heading"><div class="brand"><span class="mark"><i></i><i></i><i></i></span>${t('بيان','bayan')}</div><button class="close sidebar-close" id="closeMenu" aria-label="${t('إغلاق القائمة','Close menu')}"><svg viewBox="0 0 16 16" aria-hidden="true" focusable="false"><path d="M3 3L13 13M13 3L3 13" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg></button></div><div class="navtitle">${t('مساحة التعلّم','YOUR LEARNING SPACE')}</div><button class="navbtn ${category==='all'?'active':''}" data-cat="all">⌂ ${t('استكشف المفاهيم','Explore concepts')}</button><div class="navtitle">${t('الأقسام المحاسبية','ACCOUNTING TOPICS')}</div>${groups.map(g=>`<button class="navbtn ${category===g[0]?'active':''}" data-cat="${g[0]}"><span>${g[3]}</span>${t(g[1],g[2])}</button>`).join('')}<div class="sidebarfoot">${t('خطوة صغيرة، فهم أعمق.','Small steps. Deeper understanding.')}<div class="progress"><span style="width:${completed.size/lessons.length*100}%"></span></div><div>${n(completed.size)} / ${n(lessons.length)} ${t('مفهوم مكتمل','concepts completed')}</div></div>`;$('#header').innerHTML=`<button class="mobilemenu" aria-controls="sidebar" aria-expanded="${document.body.classList.contains('menu')}" aria-label="${t('القائمة','Menu')}">☰</button><span class="breadcrumb">${t('مساحة التعلّم / استكشف المفاهيم','Learning space / Explore concepts')}</span><div class="headtools"><button class="lang">${t('English','العربية')}</button><span class="avatar">${t('ب','b')}</span></div>`;
$('#hero').innerHTML=`<div class="hero"><div><div class="eyebrow"><span class="dot"></span>${t('تعلّم المحاسبة بالصورة والتجربة','A VISUAL WAY TO LEARN ACCOUNTING')}</div><h1>${t('المحاسبة،<br>كما لم <em>ترها</em> من قبل.','Accounting.<br>See it. <em>Understand it.</em>')}</h1><p>${t('حوّل الأرقام إلى فهم. استكشف المفاهيم، حرّك المتغيرات، وشاهد كيف تعمل المحاسبة خطوة بخطوة.','Turn numbers into understanding. Explore concepts, adjust the inputs, and see accounting work, one step at a time.')}</p><div class="actions"><button class="btn" data-open="equation">${t('ابدأ بالأساسيات','Start with the basics')} <span>↗</span></button><button class="btn secondary" id="browse">${t('تصفح المفاهيم','Browse concepts')}</button></div></div><div class="herovis"><div class="vislabel">${t('الفكرة الكبيرة، في معادلة واحدة','THE BIG PICTURE, IN ONE EQUATION')}</div><div class="equation">${['assets','liabilities','equity'].map((key,i)=>`${i?`<b aria-hidden="true">${i===1?'=':'+'}</b>`:''}<button class="tile" data-equation="${key}" aria-haspopup="dialog"><small>${t(...equationParts[key].title)}</small><strong data-equation-total="${key}" title="${n(equationParts[key].total)}">${n(equationParts[key].total)}</strong><span class="tilehint">${t('اضغط لاستكشاف الأنواع','Explore types')}</span></button>`).join('')}</div><div class="equation-inputs">${Object.entries(equationParts).map(([key,p])=>`<label>${t(...p.title)}<input type="number" data-equation-input="${key}" value="${p.total}" step="any" ${key!=='equity'?'min="0"':''} inputmode="decimal"></label>`).join('')}</div><div class="balance" id="equationBalance" aria-live="polite"></div><p class="note">${t('غيّر الإجماليات هنا، أو اضغط على البطاقات لتعديل المكونات. إجمالي الأصول والالتزامات يوزّع نسبيًا؛ تعديل الملكية يغيّر الأرباح المتراكمة.','Edit totals here, or select a tile to edit its components. Asset and liability totals are allocated proportionally; equity changes adjust accumulated earnings.')}</p><button class="reset" id="resetEquation">${t('إعادة الأرقام الأصلية','Restore original numbers')}</button></div></div>`;
$('#featured').innerHTML=`<div class="sectionhead"><h2>${t('جرّب، ثم افهم','Try it. Then understand it.')}</h2><small>${t('تجربة تفاعلية سريعة','A quick interactive experiment')}</small></div><div class="feature"><div class="featuretext"><span class="tag">${t('مختبر المعادلة المحاسبية','ACCOUNTING EQUATION LAB')}</span><h2>${t('ماذا يحدث عندما تقترض؟','What happens when you borrow?')}</h2><p>${t('ابدأ بأصول وحقوق ملكية بقيمة ٦٬٠٠٠. حرّك قيمة القرض وشاهد لماذا تكبر الأصول والالتزامات معًا.','Start with assets and equity of 6,000. Adjust the loan and see why assets and liabilities increase together.')}</p><button class="btn secondary" data-open="equation">${t('افتح الشرح الكامل','Open the full lesson')} ↗</button></div><div class="featurevisual"><div class="sliderrow"><label for="quickloan">${t('قيمة القرض','Loan amount')}</label><strong id="loanout"></strong></div><input type="range" id="quickloan" min="0" max="12000" step="500" value="4000"><div id="quickbars"></div><div class="note">${t('وحدات نقدية افتراضية • الأرقام تتغير مباشرة','Illustrative currency units • Updates live')}</div></div></div>`;
$('#library').innerHTML=`<div class="sectionhead"><h2>${t('مكتبة المفاهيم','Concept library')}</h2><small>${t(`${n(lessons.length)} مفهومًا · ${n(groups.length)} أقسام`,`${lessons.length} concepts · ${groups.length} topics`)}</small></div><div class="librarytools"><div class="tabs"><button class="tab ${category==='all'?'active':''}" data-cat="all">${t('الكل','All')}</button>${groups.map(g=>`<button class="tab ${category===g[0]?'active':''}" data-cat="${g[0]}">${t(g[1],g[2])}</button>`).join('')}</div><input class="search" type="search" aria-label="${t('البحث عن مفهوم','Search concepts')}" placeholder="${t('ابحث عن مفهوم…','Search for a concept…')}" value="${query.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/"/g,'&quot;')}"></div><div class="cards" id="cards"></div>`;
$('#path').innerHTML=`<div class="path"><div class="sectionhead"><h2>${t('لا تعرف من أين تبدأ؟','Not sure where to start?')}</h2><small>${t('مسار مقترح للمبتدئين','A suggested beginner path')}</small></div><div class="pathsteps">${['equation','double','journal','income'].map((id,i)=>{let l=lessons.find(x=>x.id===id);return `<div class="pathstep"><span>0${i+1}</span><strong>${name(l)}</strong><button data-open="${id}">${t('استكشف الدرس','Explore lesson')} ↗</button></div>`}).join('')}</div></div>`;
$('#footer').innerHTML=`<span>${t('بيان · الفهم يبدأ عندما ترى. أمثلة مبسطة للتعلّم.','Bayan · Understanding begins with seeing. Simplified learning examples.')}</span><span>${t('للتوسع:','Further reading:')} <a href="https://openstax.org/details/books/principles-financial-accounting" target="_blank" rel="noopener">OpenStax Financial</a> · <a href="https://openstax.org/details/books/principles-managerial-accounting" target="_blank" rel="noopener">Managerial</a></span>`;drawCards();quick();bind();}
function drawCards(){let list=lessons.filter(l=>(category==='all'||category===l.group)&&(`${l.ar} ${l.en} ${l.descAr} ${l.descEn}`).toLowerCase().includes(query.toLowerCase()));$('#cards').innerHTML=list.length?list.map(l=>`<button class="card" data-open="${l.id}"><div class="cardart">${lessonArt(l)}${completed.has(l.id)?'<span class="complete">✓</span>':''}</div><div class="cardbody"><span class="tag">${t(...groups.find(g=>g[0]===l.group).slice(1,3))}</span><h3>${name(l)}</h3><p>${desc(l)}</p><div class="cardbottom"><span>${t('شرح + تجربة + اختبار','Explain + experiment + check')}</span><span class="arrow">↗</span></div></div></button>`).join(''):`<div class="empty">${t('لا توجد نتائج. جرّب كلمة أخرى أو قسمًا آخر.','No results. Try another term or topic.')}</div>`;document.querySelectorAll('#cards [data-open]').forEach(b=>b.onclick=()=>openLesson(b.dataset.open));}
function bind(){bindEquationInputs();document.querySelectorAll('[data-equation]').forEach(b=>b.onclick=()=>openEquationDetails(b.dataset.equation));document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openLesson(b.dataset.open));document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{category=b.dataset.cat;setMenuOpen(false);render();$('#library').scrollIntoView({behavior:'smooth'});});$('.lang').onclick=()=>{lang=lang==='ar'?'en':'ar';localStorage.setItem('bayan-lab-lang',lang);render();if(current)lessonRender();};$('.search').oninput=e=>{query=e.target.value;drawCards();};$('#browse').onclick=()=>$('#library').scrollIntoView({behavior:'smooth'});$('#quickloan').oninput=quick;$('.mobilemenu').onclick=()=>setMenuOpen(!document.body.classList.contains('menu'));$('#closeMenu').onclick=()=>setMenuOpen(false);$('#menuBackdrop').onclick=()=>setMenuOpen(false);$('#menuBackdrop').setAttribute('aria-label',t('إغلاق القائمة','Close menu'));}
function quick(){let v=+$('#quickloan').value;$('#loanout').textContent=n(v);$('#quickbars').innerHTML=`<div class="sliderrow"><span>${t('الأصول','Assets')}: ${n(6000+v)}</span><span>=</span><span>${t('الالتزامات + الملكية','Liabilities + equity')}</span></div><div class="meter"><div style="background:#a7bb80;flex:${Math.max(v,1)};color:#344a34">${n(v)}</div><div style="background:#237e65;flex:6000">${n(6000)}</div></div><div class="sliderrow"><span>${t('القرض / الالتزامات','Loan / liabilities')}</span><span>${t('حقوق الملكية ثابتة','Equity stays constant')}</span></div>`;}
const defs={eq:[['amount','قيمة العملية','Transaction amount',0,12000,500,4000],['event','نوع العملية','Transaction type',['loan','capital','equipment']]],debit:[['amount','قيمة القيد','Entry amount',100,10000,100,2000],['event','العملية','Transaction',['capital','loan','equipment','rent']]],accrual:[['earned','خدمة مقدمة','Service earned',1000,20000,500,10000],['collected','نسبة التحصيل %','Collection %',0,100,10,40]],adjust:[['prepaid','تأمين سنوي مقدم','Annual prepayment',1200,24000,1200,12000],['months','أشهر التغطية المنقضية','Coverage months elapsed',0,12,1,3]],income:[['revenue','الإيرادات','Revenue',1000,30000,500,15000],['cogs','تكلفة المبيعات','Cost of sales',0,20000,500,6000],['expense','مصروفات التشغيل','Operating expenses',0,15000,500,3000]],cash:[['operating','صافي التشغيل','Net operating cash',-5000,15000,500,5000],['equipment','شراء معدات','Equipment purchased',0,15000,500,4000],['loan','قرض جديد','New loan',0,15000,500,2000]],equity:[['investment','استثمار جديد','New investment',0,10000,500,2000],['profit','ربح / خسارة','Profit / loss',-5000,10000,500,3000],['drawings','المسحوبات','Drawings',0,5000,500,1000]],dep:[['cost','تكلفة الأصل','Asset cost',10000,100000,5000,50000],['residual','القيمة المتبقية %','Residual value %',0,40,5,10],['life','العمر الإنتاجي بالسنوات','Useful life (years)',2,10,1,5],['year','سنوات الاستخدام','Years used',0,10,1,2]],inventory:[['sold','الوحدات المباعة','Units sold',0,200,10,120],['method','طريقة التكلفة','Cost method',['fifo','average']]],receivable:[['gross','إجمالي الذمم','Gross receivables',1000,50000,1000,20000],['rate','نسبة المخصص %','Allowance rate %',0,30,1,5]],be:[['price','سعر الوحدة','Unit price',10,150,5,50],['variable','تكلفة الوحدة المتغيرة','Unit variable cost',0,150,5,30],['fixed','التكلفة الثابتة','Fixed cost',1000,20000,500,5000],['units','الوحدات المباعة','Units sold',0,1000,25,300]],budget:[['budget','مصروف مخطط','Budgeted expense',1000,30000,500,10000],['actual','مصروف فعلي','Actual expense',0,40000,500,12000]],ratio:[['assets','أصول متداولة','Current assets',0,50000,1000,20000],['liabilities','التزامات متداولة','Current liabilities',0,30000,1000,10000]],margin:[['revenue','الإيرادات','Revenue',1000,30000,500,15000],['cost','إجمالي المصروفات','Total expenses',0,40000,500,12000]],leverage:[['assets','إجمالي الأصول','Total assets',1000,100000,1000,50000],['liabilities','إجمالي الالتزامات','Total liabilities',0,100000,1000,20000]],pv:[['future','المبلغ المستقبلي','Future amount',1000,100000,1000,10000],['rate','معدل الخصم السنوي %','Annual discount rate %',0,25,1,10],['years','عدد السنوات','Years',1,20,1,5]]};
const optLabels={loan:['الحصول على قرض','Receive a loan'],capital:['استثمار المالك','Owner investment'],equipment:['شراء معدات نقدًا','Buy equipment with cash'],rent:['دفع إيجار الفترة','Pay current-period rent'],fifo:['الوارد أولًا يصرف أولًا','First in, first out'],average:['المتوسط المرجح الدوري','Periodic weighted average']};
function openLesson(id){current=lessons.find(l=>l.id===id);values={};defs[current.mode].forEach(d=>values[d[0]]=Array.isArray(d[3])?d[3][0]:d[6]);answered=false;lessonRender();if(!$('#lesson').open)$('#lesson').showModal();$('#lesson').scrollTop=0;}
function lessonRender(){const l=current;$('#lessonContent').innerHTML=`<div class="lessonhead"><div><span class="tag">${t(...groups.find(g=>g[0]===l.group).slice(1,3))}</span><h2 id="lessonTitle">${name(l)}</h2></div><button class="close" aria-label="${t('إغلاق','Close')}"><svg viewBox="0 0 16 16" aria-hidden="true" focusable="false"><path d="M3 3L13 13M13 3L3 13" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg></button></div><div class="lessonbody"><p class="lessonintro">${desc(l)}</p><figure class="lesson-illustration">${lessonArt(l)}<figcaption>${t(...illustrationCaptions[l.id])}</figcaption></figure>${formulaMarkup(l.mode)}<div class="lab"><div class="controls">${defs[l.mode].map(d=>Array.isArray(d[3])?`<label class="control">${t(d[1],d[2])}<select data-key="${d[0]}">${d[3].map(o=>`<option value="${o}" ${values[d[0]]===o?'selected':''}>${t(...optLabels[o])}</option>`).join('')}</select></label>`:`<label class="control"><span>${t(d[1],d[2])}<input class="control-number" aria-label="${t(d[1],d[2])}" type="number" data-key="${d[0]}" min="${d[3]}" max="${d[4]}" step="any" value="${values[d[0]]}"></span><input type="range" aria-label="${t(d[1],d[2])}" data-key="${d[0]}" min="${d[3]}" max="${d[4]}" step="${d[5]}" value="${values[d[0]]}"></label>`).join('')}<button class="reset">${t('إعادة ضبط التجربة','Reset experiment')}</button></div><div class="canvas" id="result" aria-live="polite"></div></div>${l.mode==='debit'?accountNatureGuide():''}<div class="quiz" id="quiz"></div><div class="lessonfoot"><span class="note">${t('وحدات نقدية افتراضية • نموذج تعليمي مبسط','Illustrative currency units • Simplified educational model')}</span><button class="btn" id="finish" ${answered?'':'disabled'} style="opacity:${answered?1:.45}">${completed.has(l.id)?t('✓ مكتمل','✓ Completed'):t('إكمال المفهوم ✓','Mark complete ✓')}</button></div></div>`;$('#lesson .close').onclick=()=>$('#lesson').close();document.querySelectorAll('[data-key]').forEach(i=>i.oninput=()=>{if(i.tagName!=='SELECT'&&(!i.validity.valid||i.value===''))return;values[i.dataset.key]=i.tagName==='SELECT'?i.value:+i.value;document.querySelectorAll(`[data-key="${i.dataset.key}"]`).forEach(other=>{if(other!==i)other.value=i.value;});updateLab();});$('#lesson .reset').onclick=()=>openReset();$('#finish').onclick=()=>{if(!answered)return;completed.add(l.id);localStorage.setItem('bayan-lab-progress',JSON.stringify([...completed]));$('#lesson').close();render();};updateLab();quiz();}
function openReset(){defs[current.mode].forEach(d=>values[d[0]]=Array.isArray(d[3])?d[3][0]:d[6]);lessonRender();}
function metric(label,value){return `<div class="metric">${label}<strong>${value}</strong></div>`}function bar(label,v,max,color='#237e65'){return `<div class="barrow"><span>${label}</span><div class="bartrack"><i style="width:${Math.min(100,Math.abs(v)/Math.max(1,max)*100)}%;background:${v<0?'#c27b67':color}"></i></div><b>${n(v)}</b></div>`}function explain(a,e){return `<div class="explanation">${t(a,e)}</div>`}function account(title,debit,credit){return `<div class="taccount"><h4>${title}</h4><div class="tsides"><div><small>${t('مدين','Debit')}</small>${n(debit)}</div><div><small>${t('دائن','Credit')}</small>${n(credit)}</div></div></div>`}
function updateLab(){let v=values,m=current.mode,h='';if(m==='eq'){let loan=v.event==='loan'?v.amount:0,capital=v.event==='capital'?v.amount:0,assets=6000+loan+capital;h=`<span class="tag">${t('رصيد البداية: أصول وملكية ٦٬٠٠٠','Opening assets and equity: 6,000')}</span><div class="equation"><div class="tile"><small>${t('الأصول','Assets')}</small><strong>${n(assets)}</strong></div><b>=</b><div class="tile"><small>${t('الالتزامات','Liabilities')}</small><strong>${n(loan)}</strong></div><b>+</b><div class="tile"><small>${t('الملكية','Equity')}</small><strong>${n(6000+capital)}</strong></div></div>`;if(v.event==='equipment'){let a=Math.min(v.amount,6000);h+=bar(t('النقد','Cash'),6000-a,6000)+bar(t('المعدات','Equipment'),a,6000)+explain(`الشراء المطبق ${n(a)}: نقد ↓ ومعدات ↑ بالمقدار نفسه؛ مجموع الأصول ثابت. لا يمكن الإنفاق فوق النقد المتاح ٦٬٠٠٠.`,`Applied purchase ${n(a)}: cash falls and equipment rises equally; total assets stay unchanged. Purchases are capped at available cash of 6,000.`);}else h+=explain(v.event==='loan'?'القرض يزيد النقد والالتزامات بالتساوي؛ لا يحقق إيرادًا أو ربحًا.':'استثمار المالك يزيد النقد وحقوق الملكية؛ ليس إيرادًا.',v.event==='loan'?'A loan increases cash and liabilities equally; it is not revenue or profit.':'Owner investment increases cash and equity; it is not revenue.');}
else if(m==='debit'){let debit=v.event==='equipment'?t('المعدات','Equipment'):v.event==='rent'?t('مصروف الإيجار','Rent expense'):t('النقد','Cash');let credit=v.event==='capital'?t('رأس المال','Capital'):v.event==='loan'?t('القرض','Loan'):t('النقد','Cash');h=`<div class="taccounts">${account(debit,v.amount,0)}${account(credit,0,v.amount)}</div>${entryNature(v.event)}<div class="metrics">${metric(t('مجموع المدين','Total debit'),n(v.amount))}${metric(t('مجموع الدائن','Total credit'),n(v.amount))}${metric(t('الفرق','Difference'),'0')}</div>`+explain('هذه حركة قيد واحد، وليست ميزان مراجعة لمنشأة كاملة. المدين يسارًا والدائن يمينًا. تساوي الطرفين شرط أساسي، لكنه لا يثبت صحة اختيار الحسابات.','This is one entry, not a full-company trial balance. Debit is on the left, credit on the right. Equal totals are required but do not prove the account selection is correct.');}
else if(m==='accrual'){let c=v.earned*v.collected/100;h=`<div class="metrics">${metric(t('إيراد الاستحقاق','Accrual revenue'),n(v.earned))}${metric(t('إيراد نقدي','Cash-basis revenue'),n(c))}${metric(t('ذمم مدينة','Receivables'),n(v.earned-c))}</div>`+bar(t('مُحصّل','Collected'),c,v.earned)+bar(t('غير مُحصّل','Uncollected'),v.earned-c,v.earned,'#b0bc85')+explain('نفترض تقديم الخدمة كاملة في الفترة، وتحصيل جزء منها في الفترة نفسها؛ لا دفعات مقدمة أو مصروفات في هذا المثال.','The entire service is earned this period, with partial collection in the same period; this example has no advances or expenses.');}
else if(m==='adjust'){let e=v.prepaid*v.months/12;h=`<div class="metrics">${metric(t('أصل متبقٍ','Remaining asset'),n(v.prepaid-e))}${metric(t('مصروف مستهلك','Expense recognized'),n(e))}${metric(t('أشهر من ١٢','Months of 12'),n(v.months))}</div><div class="taccounts">${account(t('مصروف التأمين','Insurance expense'),e,0)}${account(t('تأمين مقدم','Prepaid insurance'),0,e)}</div>`+explain('قيد التسوية: مدين مصروف التأمين، دائن التأمين المقدم. لا نقد جديد في التسوية. نفترض تغطية متساوية خلال ١٢ شهرًا.','Adjusting entry: debit insurance expense, credit prepaid insurance. No new cash flow occurs. Coverage is assumed even across 12 months.');}
else if(m==='income'||m==='margin'){let rev=v.revenue,c=m==='margin'?v.cost:v.cogs+v.expense,p=rev-c;h=`<div class="metrics">${metric(t('الإيرادات','Revenue'),n(rev))}${metric(t('صافي الربح','Net profit'),n(p))}${metric(t('هامش الربح','Net margin'),n(p/rev*100)+'%')}</div>`+bar(t('الإيرادات','Revenue'),rev,Math.max(rev,c))+bar(t('المصروفات','Expenses'),c,Math.max(rev,c),'#b0bc85')+bar(t('صافي الربح','Net profit'),p,Math.max(rev,c))+explain('النتيجة السالبة تعني خسارة. يُستبعد أثر الضرائب والفوائد من هذا المثال المبسط، ولا نساوي الربح بالتدفق النقدي.','A negative result means a loss. This simplified example excludes taxes and interest; profit is not the same as cash flow.');}
else if(m==='cash'){let close=10000+v.operating-v.equipment+v.loan;h=`<div class="metrics">${metric(t('نقد البداية','Opening cash'),n(10000))}${metric(t('صافي التغير','Net change'),n(close-10000))}${metric(t('نقد النهاية','Closing cash'),n(close))}</div>`+bar(t('تشغيل','Operating'),v.operating,15000)+bar(t('استثمار','Investing'),-v.equipment,15000)+bar(t('تمويل','Financing'),v.loan,15000)+explain(close<0?'الناتج السلبي يدل على عجز تمويلي في السيناريو: تحتاج إلى تمويل إضافي أو تخفيض المدفوعات.':'نجمع التدفقات الموجبة والسالبة مع نقد البداية. شراء المعدات لا يُعد مصروفًا تشغيليًا فورًا.',close<0?'A negative result indicates a funding shortfall: additional funding or reduced payments are needed.':'Add positive and negative cash flows to opening cash. Buying equipment is not immediately an operating expense.');}
else if(m==='equity'){let close=10000+v.investment+v.profit-v.drawings;h=`<div class="metrics">${metric(t('ملكية البداية','Opening equity'),n(10000))}${metric(t('ربح / خسارة','Profit / loss'),n(v.profit))}${metric(t('ملكية النهاية','Closing equity'),n(close))}</div>`+bar(t('استثمار','Investment'),v.investment,10000)+bar(t('ربح','Profit'),v.profit,10000)+bar(t('مسحوبات','Drawings'),-v.drawings,10000)+explain('نفترض منشأة فردية. الربح يزيد الملكية والمسحوبات تخفضها، لكنها لا تخفض صافي الربح في قائمة الدخل.','Assumes a sole proprietorship. Profit increases equity and drawings reduce it, but drawings do not reduce income-statement profit.');}
else if(m==='dep'){let residual=v.cost*v.residual/100,annual=(v.cost-residual)/v.life,year=Math.min(v.year,v.life),acc=annual*year,book=v.cost-acc;h=`<div class="metrics">${metric(t('إهلاك سنوي','Annual depreciation'),n(annual))}${metric(t('مجمع الإهلاك','Accumulated depreciation'),n(acc))}${metric(t('القيمة الدفترية','Carrying amount'),n(book))}</div>`+bar(t('التكلفة','Cost'),v.cost,v.cost)+bar(t('القيمة الدفترية','Carrying amount'),book,v.cost)+bar(t('القيمة المتبقية','Residual value'),residual,v.cost,'#b0bc85')+explain(`الإهلاك محسوب لـ ${n(year)} سنة كاملة، ويقف عند نهاية العمر ${n(v.life)} سنوات. لا تنخفض القيمة عن المتبقي في هذا النموذج؛ نفترض بدء الاستخدام أول السنة.`,`Depreciation covers ${n(year)} full years, capped at the ${n(v.life)}-year useful life. Carrying amount does not fall below residual value here; use starts at the beginning of the year.`);}
else if(m==='inventory'){let c=v.method==='fifo'?Math.min(v.sold,100)*10+Math.max(0,v.sold-100)*16:v.sold*13;h=`<span class="tag">100 × 10 + 100 × 16 = 2,600</span><div class="metrics">${metric(t('تكلفة المبيعات','Cost of sales'),n(c))}${metric(t('مخزون النهاية','Closing inventory'),n(2600-c))}${metric(t('وحدات متبقية','Units remaining'),n(200-v.sold))}</div>`+bar(t('تكلفة المبيعات','Cost of sales'),c,2600)+bar(t('المخزون','Inventory'),2600-c,2600,'#b0bc85')+explain('في FIFO تخرج تكلفة الوحدات الأقدم أولًا. المتوسط الدوري = ٢٬٦٠٠ ÷ ٢٠٠ = ١٣ للوحدة. نفترض عدم وجود مخزون افتتاحي أو مرتجعات.','FIFO expenses the oldest unit costs first. Periodic weighted average = 2,600 / 200 = 13 per unit. Assumes no opening stock or returns.');}
else if(m==='receivable'){let a=v.gross*v.rate/100;h=`<div class="metrics">${metric(t('إجمالي الذمم','Gross receivables'),n(v.gross))}${metric(t('المخصص','Allowance'),n(a))}${metric(t('صافي الذمم','Net receivables'),n(v.gross-a))}</div>`+bar(t('صافي الذمم','Net receivables'),v.gross-a,v.gross)+bar(t('المخصص','Allowance'),a,v.gross,'#b0bc85')+explain('نفترض أن الرصيد السابق للمخصص صفر؛ قيد تكوينه مدين مصروف خسائر ائتمان ودائن مخصص. ليس المخصص خروجًا نقديًا مباشرًا.','Assumes an opening allowance of zero: debit credit-loss expense, credit allowance. Creating the allowance is not a direct cash outflow.');}
else if(m==='be'){let cm=v.price-v.variable,be=cm>0?v.fixed/cm:null,profit=v.units*cm-v.fixed,max=Math.max(v.fixed+v.variable*1000,v.price*1000,1);let y=x=>180-x/max*150;let pts=`40,${y(v.fixed)} 440,${y(v.fixed+v.variable*1000)}`;h=`<div class="metrics">${metric(t('مساهمة الوحدة','Unit contribution'),n(cm))}${metric(t('التعادل: وحدات','Break-even units'),be===null?'—':n(Math.ceil(be)))}${metric(t('ربح التشغيل','Operating profit'),n(profit))}</div><svg viewBox="0 0 480 225" role="img" aria-label="${t('مقارنة الإيرادات والتكاليف حسب الوحدات','Revenue and total cost by units')}"><path d="M40 20V180H450" fill="none" stroke="#cbd9cd"/><polyline points="40,180 440,${y(v.price*1000)}" stroke="#237e65" fill="none" stroke-width="3"/><polyline points="${pts}" stroke="#b49d63" fill="none" stroke-width="3"/><line x1="${40+v.units*.4}" x2="${40+v.units*.4}" y1="20" y2="180" stroke="#7d9183" stroke-dasharray="4"/>${be!==null&&be<=1000?`<circle cx="${40+be*.4}" cy="${y(be*v.price)}" r="5" fill="#237e65"/>`:''}<text x="40" y="198">0</text><text x="410" y="198">1,000</text><text x="60" y="220" fill="#237e65">${t('الإيرادات','Revenue')}</text><text x="220" y="220" fill="#9b864f">${t('إجمالي التكاليف','Total cost')}</text></svg>`+explain(cm<=0?'لا توجد نقطة تعادل محدودة: سعر الوحدة لا يغطي التكلفة المتغيرة. غيّر السعر أو التكلفة.':'النقطة هي تقاطع الإيراد والتكلفة. نقرّب الوحدات لأعلى للوحدات غير القابلة للتجزئة؛ الخط المتقطع يمثل حجم المبيعات المختار.',cm<=0?'No finite break-even point: unit price does not cover variable cost. Change the price or cost.':'The intersection is break-even. Units are rounded up for indivisible products; the dashed line is the selected sales volume.');}
else if(m==='budget'){let d=v.actual-v.budget;h=`<div class="metrics">${metric(t('المخطط','Budget'),n(v.budget))}${metric(t('الفعلي','Actual'),n(v.actual))}${metric(t('الانحراف','Variance'),n(d))}</div>`+bar(t('المخطط','Budget'),v.budget,Math.max(v.budget,v.actual))+bar(t('الفعلي','Actual'),v.actual,Math.max(v.budget,v.actual),'#b49d63')+explain(d>0?'انحراف غير ملائم: تجاوز المصروف المخطط. يجب البحث عن السبب قبل الحكم على الأداء.':d<0?'انحراف ملائم حسابيًا: المصروف أقل من المخطط. قد يصاحبه نقص جودة أو نشاط؛ افحص السبب.':'لا يوجد انحراف؛ الفعلي يساوي المخطط.',d>0?'Unfavorable expense variance: actual exceeds budget. Investigate the cause before judging performance.':d<0?'Numerically favorable: actual is below budget. This may accompany lower quality or activity; investigate the cause.':'No variance: actual equals budget.');}
else if(m==='ratio'||m==='leverage'){let ratio=m==='ratio'?(v.liabilities===0?null:v.assets/v.liabilities):v.liabilities/v.assets*100;h=`<div class="metrics">${metric(t('الأصول','Assets'),n(v.assets))}${metric(t('الالتزامات','Liabilities'),n(v.liabilities))}${metric(t('النسبة','Ratio'),ratio===null?'—':n(ratio)+(m==='ratio'?' ×':'%'))}</div>`+bar(t('الأصول','Assets'),v.assets,Math.max(v.assets,v.liabilities))+bar(t('الالتزامات','Liabilities'),v.liabilities,Math.max(v.assets,v.liabilities),'#b0bc85')+explain(m==='ratio'?(ratio===null?'النسبة غير معرفة لأن المقام صفر؛ لا نعرضها كرقم عادي.':'كل وحدة التزام متداول تقابلها هذه القيمة من الأصول المتداولة. لا توجد نسبة مثالية لكل المنشآت.'):'قد تتجاوز النسبة ١٠٠٪ عند وجود حقوق ملكية سالبة. لا تخلط إجمالي الالتزامات مع القروض ذات الفائدة فقط.',m==='ratio'?(ratio===null?'The ratio is undefined because the denominator is zero; it is not displayed as an ordinary number.':'Each unit of current liabilities is covered by this amount of current assets. No single ratio is ideal for every business.'):'The ratio may exceed 100% when equity is negative. Total liabilities are broader than interest-bearing debt.');}
else if(m==='pv'){let p=v.future/(1+v.rate/100)**v.years;h=`<div class="metrics">${metric(t('القيمة الحالية','Present value'),n(p))}${metric(t('القيمة المستقبلية','Future value'),n(v.future))}${metric(t('فرق الخصم','Discount difference'),n(v.future-p))}</div>`+bar(t('اليوم','Today'),p,v.future)+bar(t('المستقبل','Future'),v.future,v.future,'#b0bc85')+explain('كلما زادت المدة أو معدل الخصم، انخفضت القيمة الحالية. عند معدل صفر تتساوى القيمتان. هذا خصم مركب سنوي لدفعة واحدة.','A longer period or higher discount rate lowers present value. At zero rate, both values are equal. This is annual compound discounting of one payment.');}$('#result').innerHTML=h;}
const quizzes={
eq:['هل الحصول على قرض يحقق إيرادًا؟','Does receiving a loan create revenue?',['نعم','Yes'],['لا، يزيد الالتزامات','No, it increases liabilities'],1,'القرض التزام وليس إيرادًا.','A loan is a liability, not revenue.'],
debit:['النقد حساب طبيعته مدينة. عند دفع الإيجار نقدًا، كيف نسجّل نقص النقد؟','Cash has a normal debit balance. When paying rent in cash, how is the cash decrease recorded?',['دائن في حساب النقد','Credit to cash'],['مدين في حساب النقد','Debit to cash'],0,'الحساب ذو الطبيعة المدينة يزيد بالمدين وينقص بالدائن. القيد: مدين مصروف الإيجار، دائن النقد.','An account with a normal debit balance increases with debits and decreases with credits. Entry: debit rent expense, credit cash.'],
accrual:['قدّمنا خدمة ولم تُحصّل بعد. هل تُثبت إيرادًا على أساس الاستحقاق؟','We earned a service fee but have not collected it. Is it accrual revenue?',['نعم','Yes'],['لا','No'],0,'يُثبت الإيراد عند استحقاقه في هذا المثال، مع ذمم مدينة لحين التحصيل.','Revenue is recorded when earned here, with a receivable until collection.'],
adjust:['عند استهلاك التأمين المقدم، ماذا يحدث؟','As prepaid insurance is consumed, what happens?',['الأصل ينخفض والمصروف يزيد','Asset falls, expense rises'],['الأصل والمصروف يزيدان','Both asset and expense rise'],0,'ينخفض التأمين المقدم ويزيد مصروف التأمين؛ لا نقد جديد في التسوية.','Prepaid insurance falls and insurance expense rises; no new cash is involved.'],
income:['هل الربح يساوي دائمًا النقد المتاح؟','Is profit always equal to available cash?',['نعم','Yes'],['لا','No'],1,'قد توجد إيرادات غير محصلة ومصروفات غير نقدية.','There may be uncollected revenues and noncash expenses.'],
cash:['شراء معدات نقدًا يُصنف ضمن أي نشاط؟','Cash paid for equipment belongs to which activity?',['استثماري','Investing'],['تمويلي','Financing'],0,'شراء الأصول طويلة الأجل عادةً تدفق استثماري.','Purchasing long-term assets is generally an investing cash flow.'],
equity:['هل مسحوبات المالك مصروف في قائمة الدخل؟','Are owner drawings an income-statement expense?',['نعم','Yes'],['لا','No'],1,'تخفض المسحوبات حقوق الملكية مباشرة، وليس الربح.','Drawings directly reduce equity, not profit.'],
dep:['تكلفة ١٠٬٠٠٠، متبقي ٢٬٠٠٠، عمر ٤ سنوات. الإهلاك السنوي؟','Cost 10,000, residual 2,000, life 4 years. Annual depreciation?',['٢٬٠٠٠','2,000'],['٢٬٥٠٠','2,500'],0,'(١٠٬٠٠٠ − ٢٬٠٠٠) ÷ ٤ = ٢٬٠٠٠.','(10,000 − 2,000) / 4 = 2,000.'],
inventory:['عندما ترتفع أسعار الشراء، أيهما يعطي تكلفة بيع أقل في هذا المثال؟','With rising purchase prices, which gives lower cost of sales in this example?',['FIFO','FIFO'],['المتوسط المرجح','Weighted average'],0,'FIFO يستخدم تكلفة الدفعة الأقدم والأقل أولًا.','FIFO uses the older, lower-cost batch first.'],
receivable:['ماذا يحدث لصافي الذمم عند زيادة المخصص؟','What happens to net receivables when the allowance increases?',['ينخفض','It decreases'],['يزيد','It increases'],0,'صافي الذمم = إجمالي الذمم ناقص المخصص.','Net receivables equal gross receivables minus the allowance.'],
be:['ثابتة ١٬٠٠٠، سعر ٢٠، تكلفة متغيرة ١٠. كم وحدة للتعادل؟','Fixed cost 1,000, price 20, variable cost 10. Break-even units?',['١٠٠','100'],['٥٠','50'],0,'١٬٠٠٠ ÷ (٢٠ − ١٠) = ١٠٠ وحدة.','1,000 / (20 − 10) = 100 units.'],
budget:['مصروف فعلي أعلى من المخطط: الانحراف؟','Actual expense above budget is which variance?',['غير ملائم','Unfavorable'],['ملائم','Favorable'],0,'زيادة المصروف تعطي انحرافًا غير ملائم حسابيًا؛ نبحث عن السبب.','Expense overspending is numerically unfavorable; investigate why.'],
ratio:['أصول متداولة ٢٠٬٠٠٠ والتزامات ١٠٬٠٠٠. نسبة التداول؟','Current assets 20,000 and liabilities 10,000. Current ratio?',['٢ مرة','2 times'],['٥٠٪','50%'],0,'٢٠٬٠٠٠ ÷ ١٠٬٠٠٠ = ٢.','20,000 / 10,000 = 2.'],
margin:['ربح ٢٬٠٠٠ وإيرادات ١٠٬٠٠٠. هامش الربح؟','Profit 2,000 and revenue 10,000. Net margin?',['٢٠٪','20%'],['٥٠٪','50%'],0,'٢٬٠٠٠ ÷ ١٠٬٠٠٠ × ١٠٠ = ٢٠٪.','2,000 / 10,000 × 100 = 20%.'],
leverage:['أصول ٥٠٬٠٠٠ والتزامات ٢٠٬٠٠٠. نسبة الالتزامات للأصول؟','Assets 50,000 and liabilities 20,000. Liabilities-to-assets ratio?',['٤٠٪','40%'],['٢٥٠٪','250%'],0,'٢٠٬٠٠٠ ÷ ٥٠٬٠٠٠ × ١٠٠ = ٤٠٪.','20,000 / 50,000 × 100 = 40%.'],
pv:['عند زيادة معدل الخصم، القيمة الحالية لدفعة مستقبلية موجبة…','When the discount rate rises, the present value of a positive future payment…',['تنخفض','Decreases'],['تزيد','Increases'],0,'زيادة المقام في معادلة الخصم تخفض القيمة الحالية.','A larger denominator in the discount formula lowers present value.']};
function quiz(){const q=quizzes[current.mode];$('#quiz').innerHTML=`<span class="tag">${t('اختبر فهمك','CHECK YOUR UNDERSTANDING')}</span><h3>${t(q[0],q[1])}</h3><div class="answers">${[2,3].map((x,i)=>`<button class="answer" data-answer="${i}">${t(...q[x])}</button>`).join('')}</div><div class="feedback" aria-live="polite"></div>`;document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{let correct=+b.dataset.answer===q[4];document.querySelectorAll('[data-answer]').forEach(a=>a.classList.toggle('selected',a===b));$('.feedback').textContent=(correct?t('✓ صحيح. ','✓ Correct. '):t('حاول مجددًا. ','Try again. '))+t(q[5],q[6]);if(correct){answered=true;$('#finish').disabled=false;$('#finish').style.opacity=1;}});}
const equationParts={
assets:{title:['الأصول','Assets'],total:10000,intro:['موارد تسيطر عليها المنشأة نتيجة أحداث سابقة، ويُتوقع أن تحقق منافع اقتصادية. اضغط على كل نوع لعرض أمثلته.','Resources controlled by the entity as a result of past events, expected to provide economic benefits. Select a type to reveal examples.'],types:[
{title:['أصول متداولة','Current assets'],amount:6000,desc:['تُستخدم أو تُباع أو تتحول إلى نقد خلال الدورة التشغيلية المعتادة، أو يُتوقع تحققها خلال ١٢ شهرًا.','Used, sold or converted to cash within the normal operating cycle, or expected to be realized within 12 months.'],examples:[['النقد وما في حكمه','Cash and cash equivalents',3500],['الذمم المدينة','Accounts receivable',1500],['المخزون','Inventory',1000]],more:['ومن أمثلتها أيضًا المصروفات المدفوعة مقدمًا التي تُستهلك خلال الفترة القصيرة.','Other examples include prepaid expenses consumed in the short term.']},
{title:['أصول غير متداولة','Noncurrent assets'],amount:4000,desc:['موارد طويلة الأجل لا تُصنّف ضمن الأصول المتداولة.','Long-term resources that are not classified as current assets.'],examples:[['المعدات (قيمة دفترية)','Equipment (carrying amount)',4000]],more:['تشمل أيضًا الأراضي والمباني، والأصول غير الملموسة مثل البرامج والتراخيص، والاستثمارات طويلة الأجل.','Also includes land and buildings, intangible assets such as software and licenses, and long-term investments.']} ]},
liabilities:{title:['الالتزامات','Liabilities'],total:4000,intro:['التزامات حالية على المنشأة تجاه الآخرين، تنشأ عن أحداث سابقة ويتطلب الوفاء بها تحويل موارد. اضغط على النوع للتفاصيل.','Present obligations arising from past events that require a transfer of resources to settle. Select a type for details.'],types:[
{title:['التزامات متداولة','Current liabilities'],amount:2000,desc:['التزامات تُسوّى خلال الدورة التشغيلية المعتادة أو تستحق خلال ١٢ شهرًا، وتشمل الجزء المتداول من القروض.','Obligations settled in the normal operating cycle or due within 12 months, including the current portion of loans.'],examples:[['ذمم دائنة للموردين','Accounts payable',1500],['الجزء المتداول من القرض','Current portion of loan',500]],more:['من أمثلتها أيضًا الرواتب والمصروفات المستحقة، والدفعات المقدمة من العملاء مقابل خدمات قريبة.','Other examples include accrued salaries and expenses, and customer advances for near-term services.']},
{title:['التزامات غير متداولة','Noncurrent liabilities'],amount:2000,desc:['التزامات لا تستوفي تصنيف الالتزامات المتداولة. قد تضم الجزء طويل الأجل من القروض.','Obligations that do not meet current-liability classification, such as the long-term portion of loans.'],examples:[['قرض طويل الأجل','Long-term loan',2000]],more:['تشمل أمثلة أخرى السندات والتزامات الإيجار طويلة الأجل. يُفصل الجزء المستحق قريبًا ضمن المتداول.','Other examples include bonds and long-term lease liabilities. The near-term portion is classified separately as current.']} ]},
equity:{title:['حقوق الملكية','Equity'],total:6000,intro:['الحصة المتبقية للمالكين في الأصول بعد طرح الالتزامات: تختلف أسماء مكوناتها حسب شكل المنشأة.','The owners’ residual interest in assets after deducting liabilities: Component names vary by entity type.'],types:[
{title:['رأس المال المساهم به','Contributed capital'],amount:5000,desc:['المبالغ التي استثمرها المالك أو الشركاء؛ وفي الشركات قد تشمل رأس مال الأسهم وعلاوة الإصدار.','Amounts invested by owners or partners; for corporations, this can include share capital and share premium.'],examples:[['استثمارات المالك / المساهمين','Owner / shareholder contributions',5000]],more:['استثمار المالك يزيد حقوق الملكية ولا يُعد إيرادًا.','Owner investment increases equity and is not revenue.']},
{title:['الأرباح المتراكمة','Accumulated earnings'],amount:1500,desc:['الأرباح التي بقيت في المنشأة؛ تُسمى أرباحًا مبقاة في الشركات. الخسائر تخفض هذا الرصيد.','Profits retained in the business, called retained earnings in corporations. Losses reduce this balance.'],examples:[['أرباح متراكمة في المثال','Accumulated earnings in this example',1500]],more:['قد تتضمن حقوق الملكية أيضًا احتياطيات ومكونات دخل شامل آخر، وفق طبيعة المنشأة والإطار المحاسبي.','Equity may also include reserves and other comprehensive income components, depending on the entity and accounting framework.']},
{title:['مسحوبات أو توزيعات (تخفيض)','Drawings or distributions (deduction)'],amount:-500,desc:['مسحوبات المالك في المنشأة الفردية، أو توزيعات الأرباح في الشركة، تخفض حقوق الملكية.','Owner drawings in a sole proprietorship, or dividends in a corporation, reduce equity.'],examples:[['مسحوبات / توزيعات في المثال','Drawings / distributions in this example',-500]],more:['ليست مصروفًا تشغيليًا في قائمة الدخل. عُرضت منفصلة هنا لتوضيح أثرها؛ قد تُدمج ضمن أرصدة الملكية في القوائم.','These are not operating expenses in the income statement. Shown separately here to explain the effect; they may be reflected within equity balances in the statements.']} ]}
};
function openEquationDetails(key){const part=equationParts[key];$('#equationDetailsContent').innerHTML=`<div class="lessonhead"><div><span class="tag">${t('استكشف المعادلة المحاسبية','EXPLORE THE ACCOUNTING EQUATION')}</span><h2 id="equationDetailsTitle">${t(...part.title)}</h2></div><button class="close" id="closeEquationDetails" aria-label="${t('إغلاق','Close')}"><svg viewBox="0 0 16 16" aria-hidden="true" focusable="false"><path d="M3 3L13 13M13 3L3 13" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg></button></div><div class="lessonbody"><div class="tabs equation-tabs">${Object.entries(equationParts).map(([id,p])=>`<button class="tab ${id===key?'active':''}" data-part="${id}" aria-pressed="${id===key}">${t(...p.title)}</button>`).join('')}</div><p class="lessonintro">${t(...part.intro)}</p><div class="part-total"><span>${t('الإجمالي في المثال','Total in this example')}</span><strong id="partTotal">${n(part.total)}</strong></div><div class="equation-types">${part.types.map((type,i)=>`<details class="equation-type" ${i===0?'open':''}><summary><span>${t(...type.title)}</span><strong data-type-total="${i}">${n(type.amount)}</strong><span class="expand-symbol" aria-hidden="true"><svg viewBox="0 0 16 16" focusable="false"><path d="M8 3V13M3 8H13" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg></span></summary><div class="type-body"><p>${t(...type.desc)}</p><div class="type-examples">${type.examples.map((e,j)=>`<label class="component-input"><span>${t(e[0],e[1])}</span><input type="number" data-component="${i}:${j}" aria-label="${t(e[0],e[1])}" value="${e[2]}" step="any" ${key==='equity'?(i===2?'max="0"':i===0?'min="0"':''):'min="0"'} inputmode="decimal"></label>`).join('')}</div><p class="type-more">${t(...type.more)}</p></div></details>`).join('')}</div><p class="note">${t('أرقام تعليمية بوحدات نقدية افتراضية. تفاصيل التصنيف تعتمد على طبيعة المنشأة والإطار المحاسبي.','Illustrative amounts in hypothetical currency units. Classification details depend on the entity and accounting framework.')}</p></div>`;bindComponentInputs(key);$('#closeEquationDetails').onclick=()=>$('#equationDetails').close();document.querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>openEquationDetails(b.dataset.part));if(!$('#equationDetails').open)$('#equationDetails').showModal();}


const originalEquationParts=JSON.parse(JSON.stringify(equationParts));
const roundMoney=v=>Math.round(v*100)/100;
function refreshPart(key){const p=equationParts[key];p.types.forEach(type=>type.amount=roundMoney(type.examples.reduce((sum,e)=>sum+e[2],0)));p.total=roundMoney(p.types.reduce((sum,type)=>sum+type.amount,0));}
function changeEquationTotal(key,total){const p=equationParts[key];if(key==='equity'){p.types[1].examples[0][2]=roundMoney(total-p.types[0].amount-p.types[2].amount);}else{const rows=p.types.flatMap(type=>type.examples);const base=p.total;let remaining=roundMoney(total);rows.forEach((row,i)=>{const amount=i===rows.length-1?remaining:roundMoney(base>0?total*row[2]/base:total/rows.length);row[2]=Math.max(0,Math.min(remaining,amount));remaining=roundMoney(remaining-row[2]);});}refreshPart(key);}
function updateEquationView(){Object.entries(equationParts).forEach(([key,p])=>{const total=$(`[data-equation-total="${key}"]`);if(total){total.textContent=n(p.total);total.title=n(p.total);}const input=$(`[data-equation-input="${key}"]`);if(input&&document.activeElement!==input)input.value=p.total;});const diff=roundMoney(equationParts.assets.total-equationParts.liabilities.total-equationParts.equity.total);const status=$('#equationBalance');if(status){status.classList.toggle('unbalanced',diff!==0);status.innerHTML=diff===0?`<span>✓ ${t('المعادلة متوازنة','The equation is balanced')}</span>`:`<span>${t('المعادلة غير متوازنة','The equation is not balanced')}</span><strong>${t('الفرق: ','Difference: ')}${n(diff)}</strong>`;}}
function bindEquationInputs(){document.querySelectorAll('[data-equation-input]').forEach(input=>input.oninput=()=>{if(!input.validity.valid||!Number.isFinite(input.valueAsNumber))return;changeEquationTotal(input.dataset.equationInput,input.valueAsNumber);updateEquationView();});const reset=$('#resetEquation');if(reset)reset.onclick=()=>{Object.keys(equationParts).forEach(key=>equationParts[key]=JSON.parse(JSON.stringify(originalEquationParts[key])));updateEquationView();};updateEquationView();}
function bindComponentInputs(key){document.querySelectorAll('[data-component]').forEach(input=>input.oninput=()=>{if(!input.validity.valid||!Number.isFinite(input.valueAsNumber))return;const [i,j]=input.dataset.component.split(':').map(Number);equationParts[key].types[i].examples[j][2]=roundMoney(input.valueAsNumber);refreshPart(key);$('#partTotal').textContent=n(equationParts[key].total);document.querySelectorAll('[data-type-total]').forEach(el=>el.textContent=n(equationParts[key].types[+el.dataset.typeTotal].amount));updateEquationView();});}


const accountNatures=[
['الأصول','Assets','النقد، المعدات، الذمم المدينة','Cash, equipment, receivables','debit'],
['المصروفات','Expenses','الإيجار، الرواتب، مصروف الإهلاك','Rent, salaries, depreciation expense','debit'],
['المسحوبات والتوزيعات','Drawings & distributions','تخفيض حقوق الملكية، وليست مصروفًا','Reduce equity; not an expense','debit'],
['الالتزامات','Liabilities','القروض، الذمم الدائنة','Loans, accounts payable','credit'],
['حقوق الملكية','Equity','رأس المال والأرباح المبقاة','Capital and retained earnings','credit'],
['الإيرادات','Revenues','المبيعات وإيراد الخدمات','Sales and service revenue','credit']
];
function accountNatureGuide(){return `<section class="nature-guide"><h3>${t('طبيعة الحسابات: كيف تزيد وكيف تنقص؟','Account nature: how do balances increase and decrease?')}</h3><p>${t('الطبيعة تعني جانب الرصيد المعتاد للحساب؛ مدين ودائن جانبان للقيد، وليسا حكمًا بأن الحساب يزيد أو ينقص.','Nature means an account’s normal balance side. Debit and credit are entry sides; neither universally means increase or decrease.')}</p><div class="explanation nature-rule">${t('قاعدة التخفيض والإقفال: إذا كان الرصيد على جانب طبيعته المعتادة، نسجل عكسها لتخفيضه أو تصفيره؛ الحساب المدين يُخفض بالدائن، والحساب الدائن يُخفض بالمدين. لتصحيح خطأ، نحدد القيد الصحيح وأثر الخطأ أولًا؛ يمكن عكس القيد الخاطئ ثم تسجيل الصحيح، وليس كل تصحيح عكس طبيعة الحساب.','Reduction and closing rule: when the balance is on its normal side, use the opposite side to reduce or clear it. Credit a debit-balance account; debit a credit-balance account. For errors, first determine the correct entry and the error’s effect; you may reverse the incorrect entry then post the correct one. Not every correction is opposite to the account’s normal balance.')}</div><div class="nature-table-wrap"><table class="nature-table"><thead><tr><th scope="col">${t('نوع الحساب','Account type')}</th><th scope="col">${t('طبيعته المعتادة','Normal balance')}</th><th scope="col">${t('يزيد بـ','Increases with')}</th><th scope="col">${t('ينقص بـ','Decreases with')}</th></tr></thead><tbody>${accountNatures.map(row=>{const debit=row[4]==='debit';return `<tr><th scope="row">${t(row[0],row[1])}<small>${t(row[2],row[3])}</small></th><td><span class="nature-badge ${debit?'debit':'credit'}">${debit?t('مدينة','Debit'):t('دائنة','Credit')}</span></td><td>${debit?t('مدين','Debit'):t('دائن','Credit')} ↑</td><td>${debit?t('دائن','Credit'):t('مدين','Debit')} ↓</td></tr>`;}).join('')}</tbody></table></div><div class="explanation">${t('الحسابات المقابلة لها طبيعة عكس الحساب المرتبط بها: مجمع الإهلاك ومخصص خسائر الذمم طبيعتهما دائنة رغم ارتباطهما بالأصول. مردودات المبيعات طبيعتها مدينة رغم ارتباطها بالإيرادات.','Contra accounts have the opposite normal balance to their related account: accumulated depreciation and the receivables loss allowance have credit balances although linked to assets. Sales returns have a debit balance although linked to revenue.')}</div></section>`;}
function entryNature(event){const dr=event==='rent'?t('مصروف الإيجار: طبيعته مدينة؛ زاد بالمدين.','Rent expense: normal debit balance; increased with a debit.'):event==='equipment'?t('المعدات: أصل طبيعته مدينة؛ زاد بالمدين.','Equipment: an asset with a normal debit balance; increased with a debit.'):t('النقد: أصل طبيعته مدينة؛ زاد بالمدين.','Cash: an asset with a normal debit balance; increased with a debit.');const cr=event==='capital'?t('رأس المال: طبيعته دائنة؛ زاد بالدائن.','Capital: normal credit balance; increased with a credit.'):event==='loan'?t('القرض: التزام طبيعته دائنة؛ زاد بالدائن.','Loan: a liability with a normal credit balance; increased with a credit.'):t('النقد: أصل طبيعته مدينة؛ نقص بالدائن.','Cash: an asset with a normal debit balance; decreased with a credit.');return `<div class="entry-nature"><p>${dr}</p><p>${cr}</p></div>`;}
if(completed.delete('normal')){completed.add('double');localStorage.setItem('bayan-lab-progress',JSON.stringify([...completed]));}


function setMenuOpen(open){document.body.classList.toggle('menu',open);const toggle=$('.mobilemenu');if(toggle)toggle.setAttribute('aria-expanded',String(open));if(open)$('#closeMenu').focus();else if(toggle)toggle.focus();}
document.addEventListener('keydown',event=>{if(!document.body.classList.contains('menu'))return;if(event.key==='Escape'){event.preventDefault();setMenuOpen(false);}else if(event.key==='Tab'){const buttons=[...document.querySelectorAll('#sidebar button')];const first=buttons[0],last=buttons[buttons.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});

$('#lesson').addEventListener('close',()=>{current=null;});
